_SERVICE_SLUGS={x[0] for x in _RAW[-6:]}

def _base(): return os.environ.get("REVIEW_DEFENSE_PUBLIC_URL","https://review-defense.com").rstrip("/")+"/"
def _url(p): return urljoin(_base(),p.lstrip("/"))
def _e(x): return html.escape(str(x),quote=True)
def _pages():
    out=[]; seen_titles=set()
    for s,t,k,c in _RAW:
        title=t if t not in seen_titles else f"{t} | Cas concret"
        seen_titles.add(title)
        out.append({"path":f"/{s}/","title":title,"h1":title,"keyword":k,"cluster":c,"service":s in _SERVICE_SLUGS,
                    "description":f"{title} : vérifiez les faits, identifiez le motif pertinent, préparez les éléments utiles et suivez les prochaines étapes. "+("Aucune garantie de suppression : Google prend la décision finale." if s in _SERVICE_SLUGS else "Guide pratique et points de vigilance.")})
    return out
def _related(page,pages):
    hubs={
        "Pillar / suppression":"/suppression-avis-google/",
        "Faux avis":"/faux-avis-google/",
        "Signalement":"/signaler-un-avis-google/",
        "Refus / appel":"/que-faire-quand-google-refuse-de-supprimer-un-avis/",
        "Services":"/analyse-avis-google/",
        "Cas concrets / longue traîne":"/suppression-avis-google/",
        "Éditorial":"/suppression-avis-google/",
        "Procédure":"/signaler-un-avis-google/",
    }
    preferred={
        "Pillar / suppression":["/peut-on-supprimer-un-avis-google/","/comment-supprimer-un-avis-google/","/faux-avis-google/","/signaler-un-avis-google/"],
        "Faux avis":["/comment-reconnaitre-un-faux-avis-google/","/comment-prouver-qu-un-avis-google-est-faux/","/comment-constituer-un-dossier-contre-un-faux-avis-google/","/signaler-un-avis-google/"],
        "Signalement":["/comment-signaler-un-avis-google-etape-par-etape/","/comment-signaler-un-avis-google-google-maps/","/comment-signaler-un-avis-google-business-profile/","/comment-suivre-un-signalement-avis-google/"],
        "Refus / appel":["/pourquoi-mon-avis-google-reste-en-ligne/","/comment-faire-appel-apres-refus-suppression-avis-google/","/comment-contester-une-decision-concernant-un-avis-google/","/analyse-avis-google/"],
        "Services":["/analyse-avis-google/","/faire-supprimer-avis-google/","/service-suppression-avis-google/","/prix-suppression-avis-google/"],
    }
    by={p["path"]:p for p in pages}; out=[]
    hub=hubs.get(page["cluster"])
    if hub and hub!=page["path"] and hub in by: out.append(by[hub])
    for path in preferred.get(page["cluster"],[]):
        if len(out)>=4: break
        if path!=page["path"] and path in by and by[path] not in out: out.append(by[path])
    for p in pages:
        if len(out)>=5: break
        if p["path"]!=page["path"] and p["cluster"]==page["cluster"] and p not in out: out.append(p)
    return out[:5]
def _sections(page):
    title=page["title"]; keyword=page["keyword"]; cluster=page["cluster"]
    context={
      "Faux avis":"Examinez les indices disponibles sans transformer une suspicion en certitude : contenu, contexte de la relation, chronologie, répétitions éventuelles et éléments qui peuvent être vérifiés.",
      "Signalement":"Un signalement doit correspondre au motif réellement observable dans le contenu publié. Préparez les faits et les pièces utiles avant d’utiliser la procédure de la plateforme.",
      "Refus / appel":"Un refus ne signifie pas nécessairement que tous les éléments du dossier ont été examinés comme vous le souhaiteriez. Relisez la décision, vérifiez le motif et documentez la suite.",
      "Procédure":"La démarche doit être suivie dans l’ordre : identifier la situation, rassembler les éléments utiles, utiliser la procédure adaptée puis conserver la trace de la décision.",
      "Services":"Le service porte sur l’analyse, la qualification, la préparation et le suivi. Il ne transforme pas une hypothèse en fait établi et ne garantit pas une suppression.",
      "Cas concrets / longue traîne":"La réponse dépend des faits précis du dossier. La formulation du problème ne suffit pas à établir qu’un avis est faux, illicite ou contraire aux règles de la plateforme.",
      "Éditorial":"Deux démarches peuvent être complémentaires : répondre publiquement lorsque cela est utile et signaler lorsque le contenu semble relever d’un motif prévu par les règles.",
      "Pillar / suppression":"Un avis négatif n’est pas automatiquement supprimable. La première étape consiste à vérifier le contenu exact, son contexte et le motif pertinent avant toute démarche.",
    }.get(cluster,"Commencez par distinguer les faits observables, les éléments à vérifier et les options réellement disponibles.")
    if page["service"]:
        hs=["À quoi sert ce service ?","Ce qui est analysé","Comment le dossier est préparé","Validation et suivi","Limites du service"]
    elif cluster=="Signalement": hs=["Réponse courte","Dans quels cas signaler ?","Identifier le motif pertinent","Préparer les éléments","Effectuer et suivre le signalement","Que faire après la décision ?","Quand demander une analyse ?"]
    elif cluster=="Refus / appel": hs=["Réponse courte","Comprendre la décision","Vérifier le dossier","Conserver les éléments utiles","Préparer une éventuelle suite","Que faire si Google ne répond pas ?","Quand demander une analyse ?"]
    elif cluster=="Faux avis": hs=["Réponse courte","Dans quels cas la situation peut-elle se présenter ?","Quels indices vérifier ?","Comment documenter les faits ?","Comment signaler la situation ?","Que faire si le signalement échoue ?","Quand demander une analyse ?"]
    elif cluster=="Pillar / suppression": hs=["Réponse courte","Dans quels cas la question se pose ?","Quels éléments vérifier ?","Quels éléments factuels conserver ?","Quelles démarches sont possibles ?","Que faire en cas de refus ou d’absence de réponse ?","Quand demander une analyse professionnelle ?"]
    else: hs=["Réponse courte","Dans quels cas cette situation peut-elle se présenter ?","Quels éléments faut-il vérifier ?","Quels éléments conserver ?","Quelles démarches sont possibles ?","Que faire si Google refuse ou ne répond pas ?","Quand demander une analyse professionnelle ?"]
    out=[]
    for h in hs:
        if h=="Réponse courte":
            t=f"Pour « {title} », commencez par vérifier les faits et le contenu exact de l’avis. {context}"
        elif "motif" in h.lower():
            t=f"Le mot-clé « {keyword} » décrit une intention de recherche, pas une conclusion juridique ou factuelle. Le motif retenu doit correspondre à ce qui est réellement visible dans l’avis et aux règles applicables."
        elif "indices" in h.lower():
            t="Un indice isolé ne permet pas toujours de conclure. Comparez les affirmations de l’avis avec les éléments dont vous disposez et notez précisément ce qui est vérifiable, incertain ou contradictoire."
        elif "document" in h.lower() or "éléments" in h.lower() or "dossier" in h.lower():
            t="Conservez l’URL de l’avis, une capture datée, les échanges utiles, les dates et les pièces factuelles permettant de vérifier les affirmations. Évitez d’exposer des données personnelles qui ne sont pas nécessaires au dossier."
        elif "signal" in h.lower() or "démarches" in h.lower() or "options" in h.lower():
            t="Lorsque la situation semble relever d’un motif prévu par la plateforme, utilisez la procédure correspondante et gardez une trace de la demande. Le signalement déclenche un examen ; il ne garantit pas une suppression."
        elif "refus" in h.lower() or "suite" in h.lower() or "décision" in h.lower():
            t="Relisez le motif communiqué, vérifiez les éléments déjà transmis et identifiez les voies de suivi ou de contestation effectivement proposées. Une nouvelle démarche doit apporter une information pertinente, pas simplement répéter la précédente."
        elif "service" in h.lower() or "processus" in h.lower() or "prépar" in h.lower():
            t="Review Defense structure le dossier autour de l’analyse, de la qualification, des preuves, de la décision humaine et du suivi. Les étapes importantes restent explicites et traçables."
        elif "validation" in h.lower() or "suivi" in h.lower():
            t="Les étapes importantes nécessitent une validation humaine explicite. L’outil prépare les informations et conserve une trace du dossier ; il n’exécute pas automatiquement une action Google."
        else:
            t=context
        out.append((h,t))
    return out
def _faq_items(page):
    return [
      ("Peut-on supprimer un avis dans cette situation ?", "Cela dépend du contenu, du contexte et du motif applicable. Un avis négatif ou contesté n’est pas automatiquement supprimable."),
      ("Quels éléments faut-il vérifier ?", "Le texte de l’avis, son contexte, les faits disponibles, les dates utiles et les éléments permettant de confronter les affirmations à des faits."),
      ("Comment signaler l’avis ?", "Lorsque le contenu semble relever d’un motif prévu par la plateforme, utilisez la procédure de signalement correspondante et conservez les éléments transmis."),
      ("Que faire si Google refuse ?", "Relisez le motif communiqué, vérifiez le dossier et examinez les voies de suivi ou de contestation disponibles."),
      ("La suppression est-elle garantie ?", "Non. La plateforme concernée conserve la décision finale.")
    ]

def _schema(page):
    c=_url(page["path"])
    graph=[
      {"@type":"Organization","@id":_url("/#organization"),"name":"Review Defense","url":_url("/")},
      {"@type":"WebSite","@id":_url("/#website"),"name":"Review Defense","url":_url("/"),"publisher":{"@id":_url("/#organization")}},
      {"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Accueil","item":_url("/")},{"@type":"ListItem","position":2,"name":page["cluster"]},{"@type":"ListItem","position":3,"name":page["h1"],"item":c}]}
    ]
    graph.append({"@type":"Service" if page["service"] else "Article","@id":c+"#content","name":page["h1"],"headline":page["h1"],"description":page["description"],"url":c,"dateModified":SITE_MODIFIED,"mainEntityOfPage":{"@type":"WebPage","@id":c},"author":{"@type":"Organization","name":"Review Defense"},"publisher":{"@type":"Organization","name":"Review Defense","url":_url("/")}})
    graph.append({"@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in _faq_items(page)]})
    return {"@context":"https://schema.org","@graph":graph}
def _analysis_html():
    title="Analyse d’avis Google | Review Defense"
    description="Analysez une situation liée à un avis Google, structurez les faits disponibles et préparez un dossier avec validation humaine."
    schema=json.dumps({"@context":"https://schema.org","@graph":[{"@type":"Organization","@id":_url("/#organization"),"name":"Review Defense","url":_url("/")},{"@type":"WebSite","@id":_url("/#website"),"name":"Review Defense","url":_url("/"),"publisher":{"@id":_url("/#organization")}},{"@type":"Service","name":title,"description":description,"url":_url("/analyse-avis-google/"),"provider":{"@id":_url("/#organization")}}]},ensure_ascii=False,separators=(",",":"))
    script="""<script>(function(){window.dataLayer=window.dataLayer||[];var f=document.getElementById("rd-analysis-form");if(f){var started=false;f.addEventListener("input",function(){if(!started){started=true;window.dataLayer.push({event:"analysis_start",page:location.pathname});}});f.addEventListener("submit",function(e){e.preventDefault();window.dataLayer.push({event:"analysis_submit",page:location.pathname});location.href="/app";});}})();</script>"""
    return f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{_e(title)}</title><meta name="description" content="{_e(description)}"><meta name="robots" content="index,follow"><link rel="canonical" href="{_e(_url("/analyse-avis-google/"))}"><meta property="og:type" content="website"><meta property="og:title" content="{_e(title)}"><meta property="og:description" content="{_e(description)}"><meta property="og:url" content="{_e(_url("/analyse-avis-google/"))}"><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/public.css"><script type="application/ld+json">{schema}</script></head><body><div class="marketing"><header class="public-header"><a class="public-brand" href="/"><b class="brand-mark">◆</b> Review Defense</a><nav class="public-nav"><a href="/produit/">Produit</a><a href="/comment-ca-marche/">Comment ça fonctionne</a><a href="/services/">Services</a><a href="/tarifs/">Tarifs</a><a href="/ressources/">Ressources</a><a href="/contact/">Contact</a></nav><div class="public-actions"><a class="btn-secondary" href="/app">Connexion</a></div></header><main class="rd-analysis-main"><section class="rd-home-hero"><div class="rd-container rd-hero-grid"><div class="rd-hero-copy"><span class="rd-eyebrow-pill">ANALYSE D’AVIS GOOGLE</span><h1>Commencez par les faits.<br><span>Préparez la suite.</span></h1><p class="rd-hero-lead">Décrivez la situation, les éléments disponibles et ce que vous souhaitez vérifier. Review Defense structure l’analyse ; les décisions importantes restent humaines.</p><div class="rd-trust-line"><span>✓ Qualification</span><span>✓ Preuves</span><span>✓ Traçabilité</span><span>✓ Validation humaine</span></div></div><div class="rd-analysis-card"><div class="rd-card-kicker">ÉTAPE 01 · ANALYSE</div><h2>Décrivez votre situation</h2><p>Ne partagez ici que les informations nécessaires à l’analyse.</p><form id="rd-analysis-form"><label>URL de l’avis Google <span>(optionnel)</span><input name="review_url" type="url" placeholder="https://www.google.com/..."></label><label>Type de situation<select name="situation"><option>Avis que je souhaite examiner</option><option>Suspicion de faux avis</option><option>Signalement refusé</option><option>Plusieurs avis à examiner</option><option>Autre situation</option></select></label><label>Résumé des faits<textarea name="summary" rows="7" required placeholder="Quels faits souhaitez-vous vérifier ?"></textarea></label><button class="btn-primary rd-btn-lg" type="submit">Commencer l’analyse →</button><small>La soumission démarre le parcours Review Defense. Aucune action Google n’est exécutée automatiquement.</small></form></div></div></section><section class="rd-section rd-light"><div class="rd-container rd-value-grid"><article class="rd-value-card"><span>01</span><h2>Analyse</h2><p>Identifier les affirmations, faits et points à vérifier.</p></article><article class="rd-value-card"><span>02</span><h2>Décision</h2><p>Documenter ce qui est établi, incertain ou à confirmer.</p></article><article class="rd-value-card"><span>03</span><h2>Préparation</h2><p>Structurer les éléments utiles avant toute démarche externe.</p></article><article class="rd-value-card"><span>04</span><h2>Validation</h2><p>Une action importante reste soumise à une validation humaine explicite.</p></article></div></section><section class="rd-final-cta"><div class="rd-container"><span class="rd-eyebrow">GARDEZ LE CONTRÔLE</span><h2>L’automatisation prépare.<br><span>L’humain décide.</span></h2><p>La décision finale appartient à la plateforme concernée.</p><div class="seo-faq"><h2>Questions fréquentes</h2><details><summary>La suppression est-elle garantie ?</summary><p>Non. Review Defense prépare et structure les informations ; aucune suppression n’est garantie et la décision finale appartient à la plateforme concernée.</p></details><details><summary>Que se passe-t-il après l’analyse ?</summary><p>Le dossier peut être qualifié, documenté et soumis aux étapes de validation humaine prévues par le workflow.</p></details></div></div></section></main><footer class="public-footer"><div><a class="public-brand" href="/"><b class="brand-mark">◆</b> Review Defense</a><p>Analyse, qualification et suivi des dossiers liés aux avis en ligne.</p></div><div><b>Produit</b><a href="/produit/">Fonctionnalités</a><a href="/tarifs/">Tarifs</a></div><div><b>Ressources</b><a href="/ressources/">Guides</a><a href="/analyse-avis-google/">Analyser un avis</a></div><div><b>Sécurité</b><span>Validation humaine</span><span>Traçabilité complète</span></div></footer></div>{script}</body></html>'''
def render(path):
    if path=="/analyse-avis-google/":
        return 200,{"Content-Type":"text/html; charset=utf-8","Cache-Control":"public, max-age=300"},_analysis_html().encode()
    if path in COMMERCIAL:
        return 200,{"Content-Type":"text/html; charset=utf-8","Cache-Control":"public, max-age=300"},_commercial_html(path).encode()
    pages=_pages()
    if path=="/robots.txt":
        return 200,{"Content-Type":"text/plain; charset=utf-8","Cache-Control":"public, max-age=3600"},f"User-agent: *\nAllow: /\nDisallow: /app\nDisallow: /v1/\nDisallow: /reset-password\nDisallow: /verify-email\nDisallow: /accept-invitation\nSitemap: {_url('/sitemap.xml')}\n".encode()
    if path=="/sitemap.xml":
        paths=list(dict.fromkeys(["/"]+[x for x in COMMERCIAL if x!="/"]+[p["path"] for p in pages]))
        body='<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f"<url><loc>{_e(_url(path))}</loc><lastmod>{SITE_MODIFIED}</lastmod></url>" for path in paths)+"</urlset>"
        return 200,{"Content-Type":"application/xml; charset=utf-8","Cache-Control":"public, max-age=3600"},body.encode()
    page=next((p for p in pages if p["path"]==path),None)
    if not page: return None
    sections=''.join(f'<section><h2>{_e(h)}</h2><p>{_e(t)}</p></section>' for h,t in _sections(page))
    faq=''.join(f'<details><summary>{_e(q)}</summary><p>{_e(a)}</p></details>' for q,a in _faq_items(page))
    related=''.join(f'<li><a href="{_e(p["path"])}">{_e(p["h1"])}</a></li>' for p in _related(page,pages))
    c=_url(page["path"]); schema=json.dumps(_schema(page),ensure_ascii=False,separators=(",",":"))
    cta_label="Demander l'analyse" if page["service"] else "Analyser mon avis"
    script="""<script>(function(){window.dataLayer=window.dataLayer||[];document.addEventListener("click",function(e){var x=e.target.closest("[data-rd-track]");if(x){window.dataLayer.push(["click",x.getAttribute("data-rd-track"),location.pathname]);}});})();</script>"""
    body=f"""<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{_e(page["title"])}</title><meta name="description" content="{_e(page["description"])}"><meta name="robots" content="index,follow"><link rel="canonical" href="{_e(c)}"><meta property="og:type" content="article"><meta property="og:title" content="{_e(page["title"])}"><meta property="og:description" content="{_e(page["description"])}"><meta property="og:url" content="{_e(c)}"><link rel="stylesheet" href="/assets/app.css"><link rel="stylesheet" href="/assets/public.css"><script type="application/ld+json">{schema}</script></head><body><div class="marketing"><header class="public-header"><a class="public-brand" href="/"><b class="brand-mark">◆</b> Review Defense</a><nav class="public-nav"><a href="/produit/">Produit</a><a href="/comment-ca-marche/">Comment ça fonctionne</a><a href="/services/">Services</a><a href="/tarifs/">Tarifs</a><a href="/ressources/">Ressources</a><a href="/contact/">Contact</a></nav><div class="public-actions"><a class="btn-secondary" href="/app">Connexion</a><a class="btn-primary" href="/analyse-avis-google/">Analyser un avis →</a></div></header><main class="seo-main"><div class="seo-breadcrumb"><a href="/">Accueil</a> <span>›</span> <span>{_e(page["cluster"])}</span> <span>›</span> <span>{_e(page["h1"])}</span></div><article class="seo-article"><span class="eyebrow">{_e(page["cluster"]).upper()}</span><h1>{_e(page["h1"])}</h1><p class="seo-lead">Guide pratique sur <strong>{_e(page["keyword"])}</strong> : vérification des faits, qualification du problème, éléments à conserver et prochaines étapes.</p><div class="seo-content">{sections}</div><section class="seo-disclaimer"><strong>À retenir :</strong> un avis négatif ou contesté n’est pas automatiquement supprimable. Le signalement doit correspondre aux faits observables ; aucune suppression n’est garantie et la décision finale appartient à la plateforme.</section><section class="seo-faq"><h2>Questions fréquentes</h2>{faq}</section><section class="seo-related"><h2>À lire également</h2><ul>{related}</ul><p><a href="/signaler-un-avis-google/">Comment signaler un avis Google</a> · <a href="/analyse-avis-google/">Analyser votre avis Google</a></p></section><section class="seo-cta"><h2>Besoin d’analyser votre avis ?</h2><p>Structurez votre dossier avec Review Defense et gardez une validation humaine sur les étapes importantes.</p><a class="btn-primary" href="/analyse-avis-google/">{cta_label} →</a></section></article></main><footer class="public-footer"><div><a class="public-brand" href="/"><b class="brand-mark">◆</b> Review Defense</a><p>Analyse, qualification et suivi des dossiers liés aux avis en ligne.</p></div><div><b>Produit</b><a href="/produit/">Fonctionnalités</a><a href="/tarifs/">Tarifs</a></div><div><b>Ressources</b><a href="/ressources/">Guides</a><a href="/analyse-avis-google/">Analyser un avis</a></div><div><b>Sécurité</b><span>Validation humaine</span><span>Traçabilité complète</span></div></footer></div>{script}</body></html>"""
    return 200,{"Content-Type":"text/html; charset=utf-8","Cache-Control":"public, max-age=300"},body.encode()

def is_seo_path(path):
    return path in {"/robots.txt","/sitemap.xml"} or path in COMMERCIAL or any(p["path"]==path for p in _pages())
